        Ui.SETTINGS_INTRO to t("Choose which calls CallGuard listens to.", "चुनें कि CallGuard किन कॉल को सुने।", "CallGuard ఏ కాల్స్‌ను వినాలో ఎంచుకోండి."),
        Ui.SCOPE_LABEL to t("Analyse calls from", "इनकी कॉल का विश्लेषण करें", "వీరి కాల్స్‌ను విశ్లేషించండి"),
