        Ui.SCOPE_ALL to t("All calls", "सभी कॉल", "అన్ని కాల్స్"),
        Ui.FEEDBACK_Q to t("Was this a scam?", "क्या यह ठगी थी?", "ఇది మోసమేనా?"),
        Ui.FEEDBACK_YES to t("Yes, it was a scam", "हाँ, यह ठगी थी", "అవును, ఇది మోసం"),
