        Ui.FEEDBACK_UNSURE to t("Not sure", "पक्का नहीं पता", "ఖచ్చితంగా తెలియదు"),
        Ui.FEEDBACK_SAVED to t("Thank you. Saved on this phone only.", "धन्यवाद। सिर्फ़ इसी फ़ोन में सहेजा गया।", "ధన్యవాదాలు. ఈ ఫోన్‌లో మాత్రమే సేవ్ అయింది."),
        Ui.FEEDBACK_SAFE_NOTE to t("Marked as safe: number warnings for this caller are quieter. Requests for codes are still caught.", "सुरक्षित चिह्नित: इस कॉलर के नंबर की चेतावनियाँ कम होंगी। कोड माँगने पर फिर भी चेतावनी मिलेगी।", "సురక్షితంగా గుర్తించబడింది: ఈ కాలర్ నంబర్ హెచ్చరికలు తగ్గుతాయి. కోడ్‌లు అడిగితే మాత్రం ఇంకా హెచ్చరిస్తుంది."),
        Ui.NOTIF_WATCHING_TITLE to t("CallGuard is on", "CallGuard चालू है", "CallGuard ఆన్‌లో ఉంది"),
        Ui.NOTIF_WATCHING_BODY to t("Watching for calls. On-device only. Nothing leaves your phone.", "कॉल पर नज़र रख रहा है। सिर्फ़ फ़ोन पर। कुछ भी बाहर नहीं जाता।", "కాల్స్ కోసం చూస్తోంది. ఫోన్‌లోనే. ఏదీ బయటకు వెళ్లదు."),
        Ui.NOTIF_LISTENING_TITLE to t("CallGuard is protecting this call", "CallGuard इस कॉल की सुरक्षा कर रहा है", "CallGuard ఈ కాల్‌ను రక్షిస్తోంది"),
        Ui.NOTIF_LISTENING_BODY to t("Listening now. On-device only. Nothing leaves your phone.", "अभी सुन रहा है। सिर्फ़ फ़ोन पर। कुछ भी बाहर नहीं जाता।", "ఇప్పుడు వింటోంది. ఫోన్‌లోనే. ఏదీ బయటకు వెళ్లదు."),
        Ui.TILE_ON to t("CallGuard: ON", "CallGuard: चालू", "CallGuard: ఆన్"),
        Ui.TILE_OFF to t("CallGuard: OFF", "CallGuard: बंद", "CallGuard: ఆఫ్"),
        Ui.TR_TITLE to t("Before we ask for anything", "कुछ भी माँगने से पहले", "ఏదైనా అడిగే ముందు"),
        Ui.TR_BODY to t(
            "CallGuard will ask to hear your calls and to know when a call starts, so it can warn you if one sounds like a scam. It never records or saves the audio, and there is no internet permission for it to send anything even if it wanted to — you can check that yourself below. Only your settings, a scrambled form of numbers that called you, and your own feedback are saved, all on this phone.",
            "CallGuard आपकी कॉल सुनने और यह जानने की अनुमति माँगेगा कि कॉल कब शुरू हुई, ताकि ठगी जैसी लगने पर आपको चेतावनी दे सके। यह ऑडियो कभी रिकॉर्ड या सहेजता नहीं। इसके पास इंटरनेट की अनुमति भी नहीं है कि चाहे तो भी कुछ भेज सके — यह आप नीचे ख़ुद जाँच सकते हैं। सिर्फ़ आपकी सेटिंग, कॉल करने वालों के नंबरों का कूटबद्ध रूप, और आपका फ़ीडबैक सहेजा जाता है, सिर्फ़ इसी फ़ोन में।",
            "CallGuard మీ కాల్స్ వినడానికి, కాల్ ఎప్పుడు మొదలైందో తెలుసుకోవడానికి అనుమతి అడుగుతుంది, తద్వారా మోసంలా అనిపిస్తే హెచ్చరించగలదు. ఇది ఆడియోను ఎప్పుడూ రికార్డ్ చేయదు, సేవ్ చేయదు. దీనికి ఇంటర్నెట్ అనుమతి కూడా లేదు, కోరుకున్నా ఏదీ పంపలేదు — దీన్ని మీరే కింద తనిఖీ చేసుకోవచ్చు. మీ సెట్టింగ్‌లు, కాల్ చేసినవారి నంబర్ల గుప్త రూపం, మీ ఫీడ్‌బ్యాక్ మాత్రమే సేవ్ అవుతాయి, అదీ ఈ ఫోన్‌లోనే."),
        Ui.TR_CHECK_FMT to t("Internet access: %s", "इंटरनेट पहुँच: %s", "ఇంటర్నెట్ యాక్సెస్: %s"),
