    fun get(key: Ui, lang: Lang): String = table.getValue(key).let { (en, hi, te) -> when (lang) { Lang.EN -> en; Lang.HI -> hi; Lang.TE -> te } }
    fun fmt(key: Ui, lang: Lang, vararg args: Any): String = get(key, lang).format(*args)

    /** A language's own name, shown the same way in every language so people can always find theirs. */
    fun name(lang: Lang): String = when (lang) { Lang.EN -> "English"; Lang.HI -> "हिन्दी"; Lang.TE -> "తెలుగు" }

    fun risk(level: RiskLevel, lang: Lang): String = get(when (level) { RiskLevel.LOW -> Ui.RISK_LOW; RiskLevel.MEDIUM -> Ui.RISK_MEDIUM; RiskLevel.HIGH -> Ui.RISK_HIGH }, lang)
    fun alertLine(level: RiskLevel, lang: Lang): String = when (level) { RiskLevel.HIGH -> get(Ui.ALERT_HIGH, lang); RiskLevel.MEDIUM -> get(Ui.ALERT_MEDIUM, lang); RiskLevel.LOW -> "" }

    /** Display text for each option of each setting. */
    fun scopeOption(s: AnalyseScope, lang: Lang) = get(if (s == AnalyseScope.UNKNOWN_ONLY) Ui.SCOPE_UNKNOWN else Ui.SCOPE_ALL, lang)

    fun spokenOption(s: LanguageSetting, lang: Lang) = when (s) {
        LanguageSetting.AUTO -> get(Ui.OPT_AUTO_CALL, lang); LanguageSetting.ENGLISH -> name(Lang.EN); LanguageSetting.HINDI -> name(Lang.HI); LanguageSetting.TELUGU -> name(Lang.TE)
    }
    fun summaryOption(s: SummaryLanguage, lang: Lang) = when (s) {
        SummaryLanguage.SAME_AS_SCREEN -> get(Ui.OPT_SAME_AS_SCREEN, lang); SummaryLanguage.ENGLISH -> name(Lang.EN); SummaryLanguage.HINDI -> name(Lang.HI)
        SummaryLanguage.TELUGU -> name(Lang.TE); SummaryLanguage.MATCH_CALL -> get(Ui.OPT_MATCH_CALL, lang)
    }
}
